d692cc5e-66e1-4bc3-a2b1-119599312651	53da8f44-f976-47d9-8d84-363804c5ac70	59e13241-62d3-4bb9-a007-94cf78ecdb6e	2	约定保密义务和成果使⽤权限\n输出：\n•\n项⽬任务书（含知识产权⽬标）\n•\n经费概算（含知识产权预算明细）\n•\n合同知识产权条款审核意⻅\n阶段三：项⽬实施阶段\n主要活动：\n1. 创新成果挖掘（发明披露）\n•\n项⽬成员在产⽣创新成果后及时填写《技术交底书》\n•\n项⽬负责⼈审核技术交底书后提交知识产权专员\n•\n知识产权专员评估可申请专利性或作为技术秘密保护\n2. 专利申请与审查\n•\n知识产权专员委托专利中⼼办理专利申请\n•\n专利中⼼专利代理师撰写申请⽂件、办理提交⼿续\n•\n配合审查意⻅的答复\n•\n跟踪申请进度，及时反馈项⽬组\n3. 技术秘密管理\n•\n对不适宜申请专利的技术成果，按技术秘密进⾏保护\n•\n划定技术秘密范围，明确知悉范围\n•\n落实保密措施（审批流程、知悉范围控制、载体管理等）\n4. 知识产权维护\n•\n对已授权专利按时缴纳年费\n•\n建⽴知识产权台账（申请号/专利号、状态、权利⼈、缴费⽇期等）\n•\n定期盘点存量知识产权\n5. ⻛险监控与预警\n•\n定期监控竞争对⼿专利动态\n•\n发现潜在侵权⻛险时及时预警\n•\n必要时启动回避设计或⽆效宣告程序\n输出：\n•\n技术交底书\n•\n专利申请⽂件\n•\n技术秘密认定申请表\n•\n知识产权台账（动态更新）\n阶段四：项⽬验收阶段\n主要活动：\n1. 知识产权成果梳理与登记\n•\n项⽬组汇总所有知识产权成果（专利/软著/技术秘密等）\n•\n核对知识产权数量与⽬标完成情况\n•\n编制《项⽬知识产权成果清单》\n2. 知识产权验收\n•\n纳⼊项⽬验收评审\n•\n验收专家对知识产权成果进⾏评价	ce9e1a1ee485e123fdb3951c2db3edac4ad88ab98226f96e0a0158eca8093023	[0.048514057,0.01884941,-0.06272837,-0.06025631,0.062110353,0.003399074,0.06025631,-0.057166245,0.077560686,0.031827692,0.013287289,-0.06149234,-0.05098611,0.031827692,0.067672476,0.027501598,-0.03306372,0.05469419,0.0064891414,0.035535775,0.0015450337,-0.055312205,0.075088635,-0.010815236,-0.07261658,-0.078178704,-0.024411531,0.06705446,0.025029546,-0.073234595,-0.049132068,-0.057166245,0.048514057,0.01884941,-0.06272837,-0.06025631,0.062110353,0.003399074,0.06025631,-0.057166245,0.077560686,0.031827692,0.013287289,-0.06149234,-0.05098611,0.031827692,0.067672476,0.027501598,-0.03306372,0.05469419,0.0064891414,0.035535775,0.0015450337,-0.055312205,0.075088635,-0.010815236,-0.07261658,-0.078178704,-0.024411531,0.06705446,0.025029546,-0.073234595,-0.049132068,-0.057166245,0.048514057,0.01884941,-0.06272837,-0.06025631,0.062110353,0.003399074,0.06025631,-0.057166245,0.077560686,0.031827692,0.013287289,-0.06149234,-0.05098611,0.031827692,0.067672476,0.027501598,-0.03306372,0.05469419,0.0064891414,0.035535775,0.0015450337,-0.055312205,0.0750