7f3517e3-87cb-4400-b7e8-4db0a0d3c343	fd11e5cb-07b6-4fa6-91a1-33899622055b	d0efadca-dabf-490f-8d6e-889564f53b74	2	委托专利中心办理专利申请\n专利中心专利代理师撰写申请文件、办理提交手续\n配合审查意见的答复\n跟踪申请进度，及时反馈项目组\n技术秘密管理\n对不适宜申请专利的技术成果，按技术秘密进行保护\n划定技术秘密范围，明确知悉范围\n落实保密措施（审批流程、知悉范围控制、载体管理等）\n知识产权维护\n对已授权专利按时缴纳年费\n建立知识产权台账（申请号/专利号、状态、权利人、缴费日期等）\n定期盘点存量知识产权\n风险监控与预警\n定期监控竞争对手专利动态\n发现潜在侵权风险时及时预警\n必要时启动回避设计或无效宣告程序\n输出：\n技术交底书\n专利申请文件\n技术秘密认定申请表\n知识产权台账（动态更新）\n阶段四：项目验收阶段\n主要活动：\n知识产权成果梳理与登记\n项目组汇总所有知识产权成果（专利/软著/技术秘密等）\n核对知识产权数量与目标完成情况\n编制《项目知识产权成果清单》\n知识产权验收\n纳入项目验收评审\n验收专家对知识产权成果进行评价\n对未达标项目说明原因并提出整改措施\n成果归档保存\n所有知识产权相关文件整理归档\n向档案管理部门移交完整资料\n输出：\n项目知识产权成果清单\n验收评审意见（知识产权部分）\n归档记录\n阶段五：成果转化阶段\n主要活动：\n转化可行性评估\n对具有转化前景的成果进行技术成熟度评估\n分析市场需求和产业化潜力\n评估转化的可行性、投入产出比\n转化路径选择\n评估军转民/民参军/许可转让/作价入股等不同路径\n确定转化方式和合作伙伴\n转化实施与收益分配\n签订转化协议，明确各方权利义务\n按单位规定进行收益分配\n跟踪转化实施效果\n后续跟踪管理\n对已转化成果的市场表现进行跟踪\n评估转化效益\n总结经验，形成案例库	5dd4dc4cee006e0d82405a868e6a193cb050be705451f6f4d3e4d5084023e803	[-0.022228569,0.05444389,0.059598338,-0.03318178,0.071195856,-0.08214906,-0.011275361,-0.07377308,0.0016107659,-0.040913455,-0.024161488,0.0041879914,0.009342442,-0.013852587,-0.0660414,-0.043490678,0.031248858,-0.030604552,0.040269148,-0.009986749,-0.028027326,-0.029960245,0.0763503,0.075061694,0.05379958,0.06475279,0.055088192,-0.07699461,-0.040913455,-0.059598338,0.06733002,-0.08021614,-0.022228569,0.05444389,0.059598338,-0.03318178,0.071195856,-0.08214906,-0.011275361,-0.07377308,0.0016107659,-0.040913455,-0.024161488,0.0041879914,0.009342442,-0.013852587,-0.0660414,-0.043490678,0.031248858,-0.030604552,0.040269148,-0.009986749,-0.028027326,-0.029960245,0.0763503,0.075061694,0.05379958,0.06475279,0.055088192,-0.07699461,-0.040913455,-0.059598338,0.06733002,-0.08021614,-0.022228569,0.05444389,0.059598338,-0.03318178,0.071195856,-0.08214906,-0.011275361,-0.07377308,0.0016107659,-0.040913455,-0.024161488,0.0041879914,0.009342442,-0.013852587,-0.0660414,-0.043490678,0.031248858,-0.030604552,0.040269148,-0.009986749,-0.028027326,-0.029960245,0.0763503,