6f61c164-901a-493d-9206-571284e71cb6	3c751b8b-ead8-41db-a910-628829e93342	867c5e30-cbc2-43f3-93b8-8af4b91ca517	3	知识产权条款\n- 明确合作各方的知识产权归属\n- 约定保密义务和成果使用权限\n输出：\n- 项目任务书（含知识产权目标）\n- 经费概算（含知识产权预算明细）\n- 合同知识产权条款审核意见\n阶段三：项目实施阶段\n主要活动：\n1. 创新成果挖掘（发明披露）\n- 项目成员在产生创新成果后及时填写《技术交底书》\n- 项目负责人审核技术交底书后提交知识产权专员\n- 知识产权专员评估可申请专利性或作为技术秘密保护\n2. 专利申请与审查\n- 知识产权专员委托专利中心办理专利申请\n- 专利中心专利代理师撰写申请文件、办理提交手续\n- 配合审查意见的答复\n- 跟踪申请进度，及时反馈项目组\n3. 技术秘密管理\n- 对不适宜申请专利的技术成果，按技术秘密进行保护\n- 划定技术秘密范围，明确知悉范围\n- 落实保密措施（审批流程、知悉范围控制、载体管理等）\n4. 知识产权维护\n- 对已授权专利按时缴纳年费\n- 建立知识产权台账（申请号/专利号、状态、权利人、缴费日期等）\n- 定期盘点存量知识产权\n5. 风险监控与预警\n- 定期监控竞争对手专利动态\n- 发现潜在侵权风险时及时预警\n- 必要时启动回避设计或无效宣告程序\n输出：\n- 技术交底书\n- 专利申请文件\n- 技术秘密认定申请表\n- 知识产权台账（动态更新）\n阶段四：项目验收阶段\n主要活动：\n1. 知识产权成果梳理与登记\n- 项目组汇总所有知识产权成果（专利/软著/技术秘密等）\n- 核对知识产权数量与目标完成情况\n- 编制《项目知识产权成果清单》\n2. 知识产权验收\n- 纳入项目验收评审\n- 验收专家对知识产权成果进行评价\n- 对未达标项目说明原因并提出	fa6fef1fb2c43291d28c3bb807bcf8d37516c2ad400db41043ef15e9d8e2667b	[0.0768152,-0.010346537,0.069917515,-0.06051157,0.031666677,0.042953808,-0.048597377,0.010973601,0.05173269,0.007838286,-0.042953808,0.035429053,-0.07556108,0.037937306,0.07556108,0.052359752,-0.0065841605,-0.066155136,0.04169968,0.028531361,-0.039818496,-0.071798705,0.032920804,-0.069917515,-0.037937306,0.069917515,-0.0667822,0.066155136,0.05549507,0.061765697,-0.015990105,-0.002821783,0.0768152,-0.010346537,0.069917515,-0.06051157,0.031666677,0.042953808,-0.048597377,0.010973601,0.05173269,0.007838286,-0.042953808,0.035429053,-0.07556108,0.037937306,0.07556108,0.052359752,-0.0065841605,-0.066155136,0.04169968,0.028531361,-0.039818496,-0.071798705,0.032920804,-0.069917515,-0.037937306,0.069917515,-0.0667822,0.066155136,0.05549507,0.061765697,-0.015990105,-0.002821783,0.0768152,-0.010346537,0.069917515,-0.06051157,0.031666677,0.042953808,-0.048597377,0.010973601,0.05173269,0.007838286,-0.042953808,0.035429053,-0.07556108,0.037937306,0.07556108,0.052359752,-0.0065841605,-0.066155136,0.04169968,0.028531361,-0.039818496,-0.071798705,0.032920804,-0.069917515,-0.037