bdfe2510-c924-477c-98b3-a6c056045447	91b4a8bf-887c-4b2e-a5d5-6036eb47d916	074efe7b-2e32-4519-a5eb-0f0de701b892	2	单 | 核销应付账款、归档 | 会计凭证 | 付款后3个工作日 |\n| 10 | 供应商对账 | 应付会计 | 应付明细 | 月末与供应商对账 | 对账单 | 每月结账前 |\n## 审批权限示例\n| 单笔付款金额 | 审批权限 |\n| --- | --- |\n| ≤10,000元 | 财务经理 |\n| 10,000元＜金额≤50,000元 | 财务负责人 |\n| 50,000元＜金额≤200,000元 | 财务负责人 + 总经理 |\n| ＞200,000元 | 总经理 + 董事长/董事会授权人 |\n预付款、无合同付款、账户变更付款须额外审批。\n## 付款条件与时限\n现款现货：验收合格且发票到齐后付款。\n月结30/60/90天：按合同账期付款。\n预付款：须合同约定，且经财务负责人和总经理批准。\n质保金：按合同约定到期支付。\n付款日：建议每周固定1—2个付款日。\n## 关键控制点\n供应商准入：供应商须在合格供应商名录内。\n合同控制：无合同、无订单原则上不付款。\n三单匹配：订单、验收、发票一致。\n发票查验：防止虚开、假票、重复票。\n账户变更：供应商银行账户变更须书面确认并电话核实。\n重复付款检查：付款前查询应付明细和付款记录。\n资金计划：大额付款纳入月度资金计划。\n不相容岗位分离：申请、审批、付款、记账分离。\n## 异常处理\n| 异常情形 | 处理方式 |\n| --- | --- |\n| 发票未到 | 可暂估入账，付款须经财务负责人批准 |\n| 预付款 | 须合同约定，提供预付款保函/担保的优先 |\n| 部分付款 | 注明对应发票和合同，避免重复付款 |\n| 账户变更 | 供应商书面	45c81eed1140218b46d0203acd8e62aa7305d7be5fc68d8a3c492163c4866da8	[-0.04432734,0.054935593,-0.0738789,0.08297169,-0.08372942,-0.048116002,-0.071605705,0.0087139215,-0.04356961,0.060997453,-0.072363436,-0.0526624,0.058724254,0.010987119,-0.022353103,0.032203626,-0.009471654,-0.09282221,0.06630158,0.04735827,-0.024626302,0.05342013,0.010229386,0.007956189,-0.051146932,-0.04129641,-0.071605705,-0.021595372,0.051904663,0.0049252603,-0.0140180485,0.03068816,-0.04432734,0.054935593,-0.0738789,0.08297169,-0.08372942,-0.048116002,-0.071605705,0.0087139215,-0.04356961,0.060997453,-0.072363436,-0.0526624,0.058724254,0.010987119,-0.022353103,0.032203626,-0.009471654,-0.09282221,0.06630158,0.04735827,-0.024626302,0.05342013,0.010229386,0.007956189,-0.051146932,-0.04129641,-0.071605705,-0.021595372,0.051904663,0.0049252603,-0.0140180485,0.03068816,-0.04432734,0.054935593,-0.0738789,0.08297169,-0.08372942,-0.048116002,-0.071605705,0.0087139215,-0.04356961,0.060997453,-0.072363436,-0.0526624,0.058724254,0.010987119,-0.022353103,0.032203626,-0.009471654,-0.09282221,0.06630158,0.04735827,-0.024626302,0.05342013,0.010229386,0.007956189,-0.051146932,-0.0412