6f880fb6-adef-4028-9a3b-820e7c933ad4	79022eb6-6933-4cca-be1f-9c3411523c8b	867c5e30-cbc2-43f3-93b8-8af4b91ca517	1	要性\n国内外发展现状\n初步技术方案与主要技术指标\n预期成果与应用前景\n初步经费估算\n研制周期预估\n建议书内部审查（总师系统内部把关）\n输出：《型号研制项目立项建议书》\n模板要点：\n建议书正文不超过15页\n须附技术成熟度自评表\n须经总师签字确认\n步骤三：初审（责任人：科研管理处）\n主要活动：\n科研管理处受理立项建议书\n形式审查（材料是否齐全、格式是否规范）\n业务初审（技术方向是否符合所内发展规划）\n反馈初审意见\n通过 → 进入正式论证阶段\n退回修改 → 修改后重新提交\n不通过 → 终止流程，归档保存\n时限要求：受理后5个工作日内完成初审\n输出：《立项建议书初审意见表》\n步骤四：编制正式立项论证报告（责任人：型号总师）\n主要活动：\n按初审意见修改完善技术方案\n编制《型号研制项目立项论证报告》，须包含：\n第一章 项目概述（来源、目标、意义）\n第二章 需求分析（用户需求、作战使用需求）\n第三章 技术方案（总体方案、分系统方案、关键技术）\n第四章 主要技术指标\n第五章 研制进度计划（含里程碑节点）\n第六章 经费概算与保障条件\n第七章 知识产权分析（专利检索、侵权风险评估、知识产权布局建议）\n第八章 质量与可靠性大纲\n第九章 风险分析与应对措施\n第十章 附件（图纸、数据、引用文件等）\n提交计划财务处审核经费\n提交质量管理处审核质量大纲\n时限要求：初审通过后30个工作日内完成\n输出：《型号研制项目立项论证报告》\n步骤五：评审（责任人：科研管理处）\n主要活动：\n科研管理处组织评审专家组（不少于7人，含技术、管理、财务、知识产权等领域专家）\n召开立项评审会\n项目组汇报论证报告\n专家质询与答辩\n专	609efcc96d3e939e95ef73f2b75ad5a31b50e912bb7d551b7e632e0402156611	[-0.0213397,0.02066225,0.08434263,0.049792632,-0.01253284,-0.044373028,0.013210291,0.02066225,0.014565192,0.07553577,-0.008468135,0.077568114,0.03759852,-0.025404405,0.057922043,0.024049504,-0.06808381,-0.032178912,0.07147106,-0.074180864,0.040308323,-0.001693627,-0.028791659,-0.06808381,-0.0010161762,-0.019307347,-0.05521224,-0.08366518,-0.08502007,-0.07214851,-0.017274996,-0.074858315,-0.0213397,0.02066225,0.08434263,0.049792632,-0.01253284,-0.044373028,0.013210291,0.02066225,0.014565192,0.07553577,-0.008468135,0.077568114,0.03759852,-0.025404405,0.057922043,0.024049504,-0.06808381,-0.032178912,0.07147106,-0.074180864,0.040308323,-0.001693627,-0.028791659,-0.06808381,-0.0010161762,-0.019307347,-0.05521224,-0.08366518,-0.08502007,-0.07214851,-0.017274996,-0.074858315,-0.0213397,0.02066225,0.08434263,0.049792632,-0.01253284,-0.044373028,0.013210291,0.02066225,0.014565192,0.07553577,-0.008468135,0.077568114,0.03759852,-0.025404405,0.057922043,0.024049504,-0.06808381,-0.032178912,0.07147106,-0.074180864,0.040308323,-0.001693627,-0.028791659,-0.06808381,-0.0010