6f880fb6-adef-4028-9a3b-820e7c933ad4	79022eb6-6933-4cca-be1f-9c3411523c8b	867c5e30-cbc2-43f3-93b8-8af4b91ca517	2	目立项论证报告》\n步骤五：评审（责任人：科研管理处）\n主要活动：\n科研管理处组织评审专家组（不少于7人，含技术、管理、财务、知识产权等领域专家）\n召开立项评审会\n项目组汇报论证报告\n专家质询与答辩\n专家独立打分与评议\n形成评审意见\n评审结论分为：建议立项 / 补充完善后立项 / 不建议立项\n补充完善类须明确修改要求和时限\n时限要求：论证报告提交后10个工作日内完成评审\n输出：《型号研制项目立项评审意见》\n步骤六：审批（责任人：主管所领导/所长办公会）\n主要活动：\n根据评审意见修改完善论证报告\n按审批权限逐级报批：\n经费＜1000万元：主管所领导审批\n1000万元≤经费＜5000万元：所领导集体审议\n经费≥5000万元：所长办公会审批\n需报上级机关批准的项目，由科研管理处行文上报\n时限要求：评审通过后7个工作日内完成审批\n输出：《立项批复文件》或上级机关的批准文件\n步骤七：下达立项批复与归档（责任人：科研管理处）\n主要活动：\n正式印发立项批复文件\n向项目组下达项目任务书\n启动项目代号、经费账号\n全流程文档归档保存\n输出：《项目任务书》、归档记录\n5. 关键控制点\n点击图片可查看完整电子表格\n6. 常见问题\nQ1：立项建议书和立项论证报告有什么区别？\nA：建议书是初步的、概要性的文件，用于启动论证工作；论证报告是详细的、完整的文件，用于正式评审和审批。建议书通常在1-2周内完成，论证报告需要更充分的准备时间（通常1-2个月）。\nQ2：评审不通过怎么办？\nA：根据评审意见进行修改完善，重新提交评审。若两次评审均不通过，项目终止。\nQ3：经费概算需要做到多细？\nA：经费概算需包含：人员	7a316dd16e3f219d66a9799039bcf20aa64ae6aafd1b2d64fe1fef2005d567ef	[-0.0035684446,-0.050931435,-0.01200295,0.052877862,-0.011354142,-0.041848123,-0.061312366,0.01913984,-0.016544607,0.026925536,-0.0042172526,0.010705334,-0.045740973,0.039252892,0.074288525,-0.07623495,0.024979113,-0.034711234,0.06650283,0.027574344,0.08142542,-0.06520522,-0.05352667,-0.017842222,0.082074225,-0.062609985,0.072342105,-0.061961174,-0.079478994,0.055473093,-0.015895799,0.072342105,-0.0035684446,-0.050931435,-0.01200295,0.052877862,-0.011354142,-0.041848123,-0.061312366,0.01913984,-0.016544607,0.026925536,-0.0042172526,0.010705334,-0.045740973,0.039252892,0.074288525,-0.07623495,0.024979113,-0.034711234,0.06650283,0.027574344,0.08142542,-0.06520522,-0.05352667,-0.017842222,0.082074225,-0.062609985,0.072342105,-0.061961174,-0.079478994,0.055473093,-0.015895799,0.072342105,-0.0035684446,-0.050931435,-0.01200295,0.052877862,-0.011354142,-0.041848123,-0.061312366,0.01913984,-0.016544607,0.026925536,-0.0042172526,0.010705334,-0.045740973,0.039252892,0.074288525,-0.07623495,0.024979113,-0.034711234,0.06650283,0.027574344,0.08142542,-0.06520522,-0.05352667,-0.0