bdfe2510-c924-477c-98b3-a6c056045447	91b4a8bf-887c-4b2e-a5d5-6036eb47d916	074efe7b-2e32-4519-a5eb-0f0de701b892	0	文档五：供应商付款审批流程\n## 文档信息\n| 项目 | 内容 |\n| --- | --- |\n| 文档编号 | FIN-SOP-002 |\n| 文档名称 | 供应商付款审批流程 |\n| 版本号 | V1.0 |\n| 生效日期 | 46283 |\n| 编制部门 | 财务部 |\n| 审核人 | 财务负责人 |\n| 批准人 | 总经理/授权人 |\n| 密级 | 内部 |\n| 关键词 | 供应商付款、采购付款、三单匹配、应付账款、资金计划 |\n| 知识库标签 | 财务/付款/应付/采购/内控 |\n## 目的\n规范对公供应商付款申请、审核、审批和支付流程，确保付款基于真实合同、验收和合法发票，防止重复付款、错误付款和资金风险。\n## 适用范围\n适用于 | [公司名称] | 向供应商支付的货款、服务费、工程款、租金、咨询费、外包费及其他对公款项。\n## 职责分工\n| 角色 | 职责 |\n| --- | --- |\n| 业务部门 | 发起付款申请，确认业务真实性、验收结果 |\n| 采购部门 | 维护合同、订单、供应商信息 |\n| 应付会计 | 审核合同、订单、验收、发票，执行三单匹配 |\n| 财务经理 | 审核付款金额、账期、资金计划 |\n| 财务负责人 | 审核大额付款、异常付款 |\n| 总经理/授权人 | 审批超权限付款 |\n| 出纳 | 按审批结果支付，执行制单/复核/授权分离 |\n| 财务档案岗 | 归档付款凭证 |\n## 流程步骤\n| 序号 | 步骤 | 责任人 | 输入 | 操作要点 | 输出 | 时限 |\n| --- | --- | --- | --- | --- | ---	691cf55eed0784f36978a025b8eaee3a2b431a9abe61b68b2e4b51270f34a738	[-0.015277262,-0.06755945,0.07978126,-0.022746146,0.074349344,-0.08181823,0.0030554524,0.07842328,-0.015277262,-0.0050924206,0.022067156,-0.061448544,0.0383629,0.07231238,0.07502833,-0.047189765,-0.057374608,-0.04107886,-0.06891743,0.01799322,0.04243684,-0.020709177,0.037004925,0.0078083784,-0.055337638,-0.035646945,-0.03157301,-0.060090564,-0.07638631,-0.0512637,0.026820082,-0.048547745,-0.015277262,-0.06755945,0.07978126,-0.022746146,0.074349344,-0.08181823,0.0030554524,0.07842328,-0.015277262,-0.0050924206,0.022067156,-0.061448544,0.0383629,0.07231238,0.07502833,-0.047189765,-0.057374608,-0.04107886,-0.06891743,0.01799322,0.04243684,-0.020709177,0.037004925,0.0078083784,-0.055337638,-0.035646945,-0.03157301,-0.060090564,-0.07638631,-0.0512637,0.026820082,-0.048547745,-0.015277262,-0.06755945,0.07978126,-0.022746146,0.074349344,-0.08181823,0.0030554524,0.07842328,-0.015277262,-0.0050924206,0.022067156,-0.061448544,0.0383629,0.07231238,0.07502833,-0.047189765,-0.057374608,-0.04107886,-0.06891743,0.01799322,0.04243684,-0.020709177,0.037004925,0.0078083784,-0.055337638,-0.03