24eb24c0-43c7-4ad0-aec2-04fe6cc876b4	91b4a8bf-887c-4b2e-a5d5-6036eb47d916	074efe7b-2e32-4519-a5eb-0f0de701b892	1	→ 财务模块 → 差旅报销 → 关联出差申请单\n逐项录入费用明细，上传票据扫描件\n系统自动校验标准，超标项标红\n第四步：审批流转\n直属主管审批（金额 < 5000 元）\n部门总监审批（5000 元 ≤ 金额 < 20000 元）\nCFO 审批（金额 ≥ 20000 元）\n第五步：财务打款\n审批通过后，财务部 5 个工作日内 完成审核\n每月 15 日和 30 日 统一打款至工资卡\n报销状态可在 OA 中实时查询\n### 不予报销的情形\n无有效发票或票据造假\n超出标准且未事前审批\n出差申请单未关联\n超过 60 天未提交（特殊情况需财务总监特批）\n与公务无关的个人消费\n### 特殊情况\n紧急出差：可先出差后补申请，但需在返回后 3 日内补办\n多人同行：可合并报销，但需注明同行人员\n境外差旅：需额外提供汇率换算说明，按实际汇率结算\n### 常见问题\nQ：发票丢失怎么办？\nA：需提供发票复印件 + 情况说明，由部门总监签字确认，金额超过 1000 元需财务总监审批。\nQ：出差期间请病假，餐补怎么算？\nA：病假当天不计餐补，需提供医院证明。	9197e6d1350066909d2cd91119a903749003e90dc7bd582c51ea580dafa39380	[0.011708203,0.015722444,0.06857662,0.054526772,-0.049843494,-0.08530262,-0.017060524,0.011039163,0.019736685,-0.055864856,0.059879094,-0.07392894,-0.06857662,0.027765168,-0.0832955,-0.007693962,0.011039163,-0.0832955,0.07058374,-0.0766051,0.04783637,0.04114597,-0.026427086,-0.055864856,-0.031110369,0.07125278,-0.026427086,-0.0766051,0.03177941,0.023750925,0.013046283,0.0003345201,0.011708203,0.015722444,0.06857662,0.054526772,-0.049843494,-0.08530262,-0.017060524,0.011039163,0.019736685,-0.055864856,0.059879094,-0.07392894,-0.06857662,0.027765168,-0.0832955,-0.007693962,0.011039163,-0.0832955,0.07058374,-0.0766051,0.04783637,0.04114597,-0.026427086,-0.055864856,-0.031110369,0.07125278,-0.026427086,-0.0766051,0.03177941,0.023750925,0.013046283,0.0003345201,0.011708203,0.015722444,0.06857662,0.054526772,-0.049843494,-0.08530262,-0.017060524,0.011039163,0.019736685,-0.055864856,0.059879094,-0.07392894,-0.06857662,0.027765168,-0.0832955,-0.007693962,0.011039163,-0.0832955,0.07058374,-0.0766051,0.04783637,0.04114597,-0.026427086,-0.055864856,-0.031110369,0.07125278,-0.026427086,-0.0766051,0.03177941,0.023750925,0.013046283,0.0003345201,0.011708203,0.015722444,0.06857662,0.054526772,-0.049843494,-0.08530262,-0.017060524,0.011039163,0.019736685,-0.055864856,0.059879094,-0.07392894,-0.06857662,0.027765168,-0.08